@layer components {
  :where([data-control-family="field"][data-field-kind="input-group"][data-slot="addon"]),

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]),

  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]),

  :where([data-control-family="field"][data-field-kind="native-select"][data-slot="icon"]) {
    color: var(--muted-foreground);
  }

  :where([data-input-group-part="input"]),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="input"]) {
    outline: none;
    background: transparent;
    color: var(--foreground);
  }

  :where([data-input-group-part="input"])::placeholder,

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="input"])::placeholder {
    color: var(--muted-foreground);
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]),

  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]) {
    border-radius: var(--radius-control);
    outline: none;
    transition-property: color, box-shadow;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  @media (hover: hover) {
    :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]:hover),

    :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]:hover),

    :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]:hover),

    :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]:hover) {
      color: var(--foreground);
    }
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]:focus-visible),

  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]:focus-visible) {
    box-shadow: 0 0 0 2px var(--focus-ring, oklch(from var(--foreground) l c h / 0.2));
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]:disabled),

  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]:disabled) {
    cursor: not-allowed;
    opacity: 0.45;
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="icon"]) {
    transition-property: rotate;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-popup-open] :where([data-control-family="field"][data-field-kind="combobox"][data-slot="icon"])) {
    rotate: 180deg;
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]) {
    border-inline-end: 1px solid var(--border);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]) {
    border-inline-start: 1px solid var(--border);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]) {
    outline: none;
    transition-property: color, background-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]:active),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]:active) {
    background: oklch(from var(--foreground) l c h / 0.06);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"][data-disabled]),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"][data-disabled]) {
    color: oklch(from var(--muted-foreground) l c h / 0.5);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="scrub-cursor"]) {
    color: var(--foreground);
    filter: drop-shadow(0 1px 1px oklch(0 0 0 / 0.05));
  }

  :where([data-control-family="field"][data-field-kind="input-otp"][data-slot="separator"]) {
    border-radius: 9999px;
    background: var(--border);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="title"]) {
    color: var(--foreground);
    font-size: var(--text-label);
    font-weight: 500;
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="label"]) {
    color: var(--foreground);
    font-size: var(--text-label);
    font-weight: 500;
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="label"][data-disabled]) {
    opacity: 0.5;
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-caption);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="error"]) {
    color: var(--destructive-text);
    font-size: var(--text-caption);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="separator"]) {
    font-size: var(--text-caption);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="separator-content"]) {
    background-color: var(--background);
    color: var(--muted-foreground);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="set"]) {
    border-width: 0px;
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="legend"]) {
    color: var(--foreground);
    font-size: var(--text-label);
    font-weight: 600;
  }
}

@layer components {
  :where([data-control-family="field"][data-control="true"]) {
    --field-radius: var(--radius-control);
    --field-background: oklch(from var(--card) l c h / 0.72);
    --field-foreground: var(--foreground);
    --field-border-color: var(--border);
    --field-border-width: 1px;
    --field-shadow: var(--shadow-sm);
    --field-backdrop-filter: blur(0px);
    --field-focus-border-color: var(--border);
    --field-focus-ring-color: var(--focus-ring, oklch(from var(--foreground) l c h / 0.2));
    --field-focus-ring-width: 2px;
    border: var(--field-border-width) solid var(--field-border-color);
    border-radius: var(--field-radius);
    outline: none;
    background: var(--field-background);
    box-shadow: var(--field-shadow);
    color: var(--field-foreground);
    backdrop-filter: var(--field-backdrop-filter);
  }

  :where([data-control-family="field"][data-control="true"]:not([data-control-family="field"][data-field-kind="autocomplete"]):not(
        [data-control-family="field"][data-field-kind="combobox"]
      )
  ) {
    transition-property: color, background-color, border-color, box-shadow, opacity, backdrop-filter;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="field"][data-control="true"])::placeholder {
    color: var(--muted-foreground);
  }

  @media (hover: hover) {
    :where(
      [data-control-family="field"][data-field-kind="autocomplete"]:hover,
      [data-control-family="field"][data-field-kind="combobox"]:hover,
      [data-control-family="field"][data-field-kind="native-select"]:hover,
      [data-control-family="field"][data-field-kind="number-field"]:hover
    ) {
      background: oklch(from var(--foreground) l c h / 0.05);
    }
  }

  :where([data-control-family="field"][data-control="true"]:is(:focus-visible, :focus-within)) {
    border-color: var(--field-focus-border-color);
    box-shadow: 0 0 0 var(--field-focus-ring-width) var(--field-focus-ring-color), var(--field-shadow);
  }

  :where([data-control-family="field"][data-control="true"][data-invalid]),

  :where([data-control-family="field"][data-control="true"][aria-invalid="true"]) {
    box-shadow: 0 0 0 2px var(--destructive), var(--field-shadow);
  }

  :where([data-control-family="field"][data-control="true"]:disabled),

  :where([data-control-family="field"][data-control="true"][data-disabled]) {
    cursor: not-allowed;
    opacity: 0.5;
  }


  :where([data-control-family="field"][data-field-kind="input-otp"][data-slot="slot"]) {
    --_field-input-otp-slot-text-align: center;
    text-align: var(--_field-input-otp-slot-text-align);
    font-size: var(--text-body);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="input"]) {
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="native-select"][data-slot="root"]) {
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="drag-icon"]) {
    color: var(--foreground);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="input"]) {
    --_field-number-field-input-text-align: center;
    text-align: var(--_field-number-field-input-text-align);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="group"]) {
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="textarea"][data-slot="root"]) {
    font-size: var(--text-body);
  }

  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="input"]) {
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="input-otp"][data-slot="slot"]) {
    --_field-input-otp-slot-number-style: tabular-nums;
    font-variant-numeric: var(--_field-input-otp-slot-number-style);
  }

  :where([data-control-family="field"][data-field-kind="native-select"][data-slot="root"]) {
    appearance: none;
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="input"]) {
    --_field-number-field-input-number-style: tabular-nums;
    font-variant-numeric: var(--_field-number-field-input-number-style);
  }
}

@property --field-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --field-background {
  syntax: "*";
  inherits: true;
}

@property --field-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --field-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --field-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --field-shadow {
  syntax: "*";
  inherits: true;
}

@property --field-backdrop-filter {
  syntax: "*";
  inherits: true;
}

@property --field-focus-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --field-focus-ring-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --field-focus-ring-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@layer components {
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="content"]) {
    --_popup-alert-dialog-content-outline: none;
    outline-style: var(--_popup-alert-dialog-content-outline);
  }

  :where([data-control-family="popup"][data-popup-kind="hover-card"][data-slot="positioner"]) {
    --_popup-hover-card-positioner-outline: none;
    outline-style: var(--_popup-hover-card-positioner-outline);
  }

  :where([data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="link"]) {
    --_popup-navigation-menu-link-decoration: none;
    text-decoration-line: var(--_popup-navigation-menu-link-decoration);
  }

  :where([data-control-family="popup"][data-popup-kind="menubar"][data-slot="sub-trigger-indicator"]) {
    line-height: 1;
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"]) {
    --_popup-rich-tooltip-content-text-align: left;
    text-align: var(--_popup-rich-tooltip-content-text-align);
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"][data-starting-style]) {
    --_popup-rich-tooltip-content-opacity: 0%;
    opacity: var(--_popup-rich-tooltip-content-opacity);
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"][data-ending-style]) {
    --_popup-rich-tooltip-content-opacity: 0%;
    opacity: var(--_popup-rich-tooltip-content-opacity);
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="positioner"]) {
    --_popup-rich-tooltip-positioner-outline: none;
    outline-style: var(--_popup-rich-tooltip-positioner-outline);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="content"]) {
    --_popup-dialog-content-outline: none;
    outline-style: var(--_popup-dialog-content-outline);
  }

  :where([data-control-family="popup"][data-popup-kind="color-picker"][data-slot="positioner"]) {
    --_popup-color-picker-positioner-outline: none;
    outline-style: var(--_popup-color-picker-positioner-outline);
  }

  :where([data-control-family="popup"][data-popup-kind="context-menu"][data-slot="sub-trigger-indicator"]) {
    line-height: 1;
  }

  :where([data-control-family="button"][data-slot="root"][data-dialog-part="close"]) {
    --_popup-button-root-close-opacity: 70%;
    opacity: var(--_popup-button-root-close-opacity);
  }

  @media (hover: hover) {
    :where([data-control-family="button"][data-slot="root"][data-dialog-part="close"]:hover) {
      --_popup-button-root-close-opacity: 100%;
      opacity: var(--_popup-button-root-close-opacity);
    }
  }
}

@layer components {
  :where([data-control-family="popup"][data-popup-kind="model-switcher"][data-slot="hint"]) {
    font-size: var(--text-micro);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="group-label"]) {
    font-size: var(--text-micro);
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.08em;
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="empty"]) {
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="icon"]) {
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="positioner"]) {
    --_popup-trigger-menu-positioner-outline: none;
    outline-style: var(--_popup-trigger-menu-positioner-outline);
  }

  :where([data-control-family="popup"][data-popup-kind="combobox"][data-slot="group-label"]) {
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="combobox"][data-slot="item-indicator"]) {
    color: var(--foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="combobox"][data-slot="empty"]) {
    --_popup-combobox-empty-text-align: center;
    text-align: var(--_popup-combobox-empty-text-align);
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="combobox"][data-slot="positioner"]) {
    --_popup-combobox-positioner-outline: none;
    outline-style: var(--_popup-combobox-positioner-outline);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="group"] [cmdk-group-heading]) {
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.08em;
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="empty"]) {
    --_popup-command-empty-text-align: center;
    text-align: var(--_popup-command-empty-text-align);
    font-size: var(--text-body);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input"]) {
    --_popup-command-input-outline: none;
    outline-style: var(--_popup-command-input-outline);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input-icon"]) {
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="dialog-root"]) {
    --_popup-command-dialog-root-transition-property: grid-template-rows;
    transition-property: var(--_popup-command-dialog-root-transition-property);
    transition-duration: var(--duration-slow);
    transition-timing-function: var(--ease-emphasized);
    transition-delay: var(--duration-fast);
  }

  :where([data-control-family="popup"][data-popup-kind="autocomplete"][data-slot="group-label"]) {
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="autocomplete"][data-slot="empty"]) {
    --_popup-autocomplete-empty-text-align: center;
    text-align: var(--_popup-autocomplete-empty-text-align);
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="autocomplete"][data-slot="positioner"]) {
    --_popup-autocomplete-positioner-outline: none;
    outline-style: var(--_popup-autocomplete-positioner-outline);
  }
}

@layer components {
  :where([data-control-family="popup"][data-sheet-part="content"]) {
    --_popup-sheet-content-outline: none;
    outline-style: var(--_popup-sheet-content-outline);
    --_popup-sheet-content-transition-property: translate;
    transition-property: var(--_popup-sheet-content-transition-property);
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
    border-radius: 0;
    border-style: solid;
    border-width: 0px;
  }

  :where([data-control-family="popup"][data-sheet-part="content"][data-side="left"]:is([data-starting-style], [data-ending-style])) {
    translate: -100% 0;
  }

  :where([data-control-family="popup"][data-sheet-part="content"][data-side="right"]:is([data-starting-style], [data-ending-style])) {
    translate: 100% 0;
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="arrow-shape"]) {
    fill: currentcolor;
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"]) {
    font-size: var(--text-xs);
    line-height: var(--text-xs--line-height);
    --_popup-tooltip-content-text-wrap: balance;
    text-wrap: var(--_popup-tooltip-content-text-wrap);
    --_popup-tooltip-content-outline: none;
    outline-style: var(--_popup-tooltip-content-outline);
    --_popup-tooltip-content-transition-property: opacity,scale;
    transition-property: var(--_popup-tooltip-content-transition-property);
    transition-timing-function: var(--ease-standard);
    transition-duration: var(--duration-fast);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-instant]) {
    --_popup-tooltip-content-transition-property: none;
    transition-property: var(--_popup-tooltip-content-transition-property);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-ending-style]) {
    --_popup-tooltip-content-opacity: 0%;
    opacity: var(--_popup-tooltip-content-opacity);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-starting-style]) {
    --_popup-tooltip-content-opacity: 0%;
    opacity: var(--_popup-tooltip-content-opacity);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="positioner"]) {
    --_popup-tooltip-positioner-outline: none;
    outline-style: var(--_popup-tooltip-positioner-outline);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-popup-part="surface"]:not([data-arrow="true"])) {
    --_popup-tooltip-content-radius: var(--popup-radius);
    border-radius: var(--_popup-tooltip-content-radius);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-popup-part="surface"][data-arrow="true"]) {
    --_popup-tooltip-content-radius: clamp(0px, var(--popup-radius), 3px);
    border-radius: var(--_popup-tooltip-content-radius);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="arrow"][data-side="top"]) {
    --_popup-tooltip-arrow-rotate: 180deg;
    rotate: var(--_popup-tooltip-arrow-rotate);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="arrow"][data-side="left"]) {
    --_popup-tooltip-arrow-rotate: 90deg;
    rotate: var(--_popup-tooltip-arrow-rotate);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="arrow"][data-side="right"]) {
    --_popup-tooltip-arrow-rotate: calc(90deg * -1);
    rotate: var(--_popup-tooltip-arrow-rotate);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-ending-style]) {
    --_popup-tooltip-content-scale: 95% 95%;
    scale: var(--_popup-tooltip-content-scale);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-starting-style]) {
    --_popup-tooltip-content-scale: 95% 95%;
    scale: var(--_popup-tooltip-content-scale);
  }
}

@layer components {
  :where([data-control-family="popup"][data-popup-part="surface"], [data-control-family="popup"][data-popup-part="list-surface"], [data-control-family="popup"][data-popup-part="bar"]) {
    --popup-radius: var(--radius-popover);
    --popup-background: var(--popover);
    --popup-foreground: var(--popover-foreground);
    --popup-border-color: var(--border);
    --popup-border-width: 1px;
    --popup-shadow: var(--shadow-pop);
    --popup-backdrop-blur: var(--backdrop-blur-popover);
    --popup-item-radius: var(--radius-popup-item);
